def item(id,name,spec,price,status,why,store='PH electrical supplier / Raon; exact supplier quote pending',source=None,qty=1):
    return dict(id=id,name=name,spec=spec,price=price,status=status,why=why,store=store,source=source,qty=qty,unit='pc',category='Power-control materials')
parts=[
item('B06','Fryer run contactor K1','Candidate LS Metasol MC-9b, genuine 24 V DC coil variant, 3 main NO poles and 1 NO + 1 NC auxiliary; verify at least 20 A AC-1 heater switching rating and exact order code',None,'QUOTE NEEDED; coil variant and actual ratings to confirm','Switches the fryer during normal cooking; the fryer thermostat still regulates heat. Low-voltage coil keeps controller/button wiring away from heater mains.'),
item('B07','Independent power-stop contactor K0','Candidate same 24 V DC coil family; poles/rating must cover fryer and motor-supply AC input including inrush; hardwired E-stop and manual restart; ordinary contactor does not certify a safety system',None,'QUOTE NEEDED; combined load/inrush and stop arrangement to verify','Removes heater and motor-supply power independently of the Arduino. Mechanical load holding is still required when the basket motor loses power.'),
item('B08.1','Arduino-to-contactor relay interface','Circuitrocks SKU 2833, 5 V single-channel optocoupler relay board candidate; verify actual relay DC contact rating for 24 V coil and suppression; signal interface only',65,'LISTED; currently SOLD OUT; DC rating/trigger behavior to verify','Allows the Arduino to switch K1 coil current. Its contacts carry low-voltage coil power, not the 2400 W heater.',store='Circuitrocks PH',source='S11'),
item('B08.2','24 V contactor control supply','Candidate genuine MEAN WELL HDR-15-24, 24 V DC 0.63 A / 15.2 W, DIN rail; capacity conditional on actual two-coil pickup/holding loads and temperature derating',1765.40,'LISTED inc. VAT; model/load match pending','Powers the proposed 24 V contactor coils while the power-stop contactor is off. It is separate from A17 motor supply. Do not buy if a verified alternative control-power arrangement replaces it.',store='RS Philippines / authorized MEAN WELL PH supplier',source='S12'),
item('B08.3','Hardwired RESET pushbutton','One momentary normally-open panel control rated for the selected 24 V control circuit; exact model/contact block pending',None,'QUOTE NEEDED; final manual-restart circuit to verify','Lets the operator deliberately restore power after emergency stop/power loss. Releasing the emergency stop alone must not cause automatic restart.'),
item('B08.4','Contactor coil suppression accessories','Manufacturer-compatible suppression for the selected DC coils; supplier checks built-in suppression first; budget one set for up to two coils',None,'QUOTE NEEDED; buy only missing accessories','Limits coil switch-off voltage spikes. Suppression type affects contactor release time, so a generic diode must not be selected blindly for an emergency-stop circuit.'),
item('B08.5','Additional 24 V control wire and fuse parts','Dedicated control-branch fuse/holder and low-voltage panel wire; ratings/length after coil data; reuse suitable existing A14 pieces instead of rebuying',150,'ESTIMATE; additional pieces only','Protects and connects the new control-power branch. This is separate from high-current motor wiring already in A14/B04.'),
item('B09.1','RCBO if existing supply protection is inadequate','Candidate CHINT NB4LE 2P C16, Type A, 30 mA, 230/240 V, 6 kA, manufacturer code 292721; current/curve/breaking capacity/frequency and isolation suitability depend on actual circuit',None,'QUOTE NEEDED; need/type to verify at school outlet','Combines overload/short-circuit and earth-leakage protection. If a suitable verified device already protects this circuit, do not buy another automatically.',source='S14'),
item('B09.2','Covered mains enclosure with mounting plate','Candidate approx. 300 x 300 x 150 mm suitable metal/plastic electrical enclosure; confirm component clearances, insulation, splash location and metal bonding',800,'ESTIMATE PHP 500-1200; exact enclosure quote needed','Houses contactors, control supply and protected mains terminals. This is the mains compartment; B03 already budgets the separate low-voltage electronics box.'),
item('B09.3','DIN rail and mounting/end-stop kit','35 mm DIN rail, lengths determined by layout, end stops and mounting hardware; omit rail supplied with enclosure',100,'ESTIMATE PHP 50-150; additional pieces only','Secures contactors/supply/protection in the enclosure. Do not charge for the same mounting hardware again in B05.'),
item('B09.4','Covered mains terminals and earth bar','Current/voltage-rated terminal blocks, covers and protective-earth distribution; model/count after conductor and fault-current review',200,'ESTIMATE PHP 150-350; final ratings/count pending','Connects incoming power and appliance branches securely and bonds exposed metal. Protective earth is never switched by the Arduino, a relay or an emergency stop.'),
item('B09.5','Mains cord, matching grounded plug and controlled outlet','Provisional 3G2.5 mm2 flexible copper cable allowance plus genuine matching grounded 250 V plug/socket rated at least 16 A; actual type, length, ampacity and protection must be checked; retain factory fryer cord',850,'ESTIMATE PHP 500-1200; lengths and outlet type pending','Provides a controlled connection for the intact fryer and supply. This is mains wiring, separate from B04 DC harness; no cheap ungrounded or universal adapter is presumed suitable.'),
item('B09.6','Mains cable glands, ferrules and identification','Mains-compartment strain relief, appropriately sized ferrules/sleeves and wire labels; only pieces not included with enclosure/other kits',150,'ESTIMATE PHP 100-250; avoid duplicate kits','Keeps cables from pulling out and makes connections identifiable. B04/B05 already cover DC/external sensor pieces; these are additional mains-only parts.')]
