def mdrow(x):
    price='Quote needed' if x['price'] is None else f"{x['price']:,.2f}"
    total='Quote needed' if x['price'] is None else f"{x['price']*x['qty']:,.2f}"
    ref=f" [{x['source']}]" if x.get('source') else ''
    return f"| {x['id']} | {x['name']} | {x['spec']} | {x['qty']} | {price} | {total} | {x['store']}. {x['status']}{ref} | {x['why']} |"
